149:     private String evaluate(CompositeStringExpression compositeStringExpression, Map<String, ?> context) {
150:         StringBuilder sb = new StringBuilder();
151:         Expression[] subExpressions = compositeStringExpression.getExpressions();
152: 
153:         for (Expression subExpression : subExpressions) {
154:             if (subExpression instanceof LiteralExpression) {
155:                 sb.append(subExpression.getValue());
156: 
157:                 continue;
158:             } else if (subExpression instanceof SpelExpression) {
159:                 sb.append(evaluate(ACCESSOR_PREFIX + subExpression.getExpressionString() + ACCESSOR_SUFFIX, context));
160: 
161:                 continue;
162:             }
163: 
164:             Class<? extends Expression> subExpressionClass = subExpression.getClass();
165: 
166:             throw new IllegalArgumentException("unknown expression type: " + subExpressionClass.getName());
167:         }
168: 
169:         return sb.toString();
170:     }
