758:         }
759: 
760:         List<String> missingRequiredProperties = new ArrayList<>();
761: 
762:         if (parameterMap != null && properties != null) {
763:             checkRequiredProperties(properties, parameterMap, "", missingRequiredProperties);
764:         }
765: 
766:         return new WorkflowNodeStructure(operationType, parameterMap, properties, missingRequiredProperties);
767:     }
