258:     private ConnectedUserProject checkConnectedUserProject(String externalUserId, Environment environment) {
259:         return connectUserProjectService
260:             .fetchConnectUserProject(externalUserId, environment)
261:             .orElseGet(() -> {
262:                 Project project = new Project();
263: 
264:                 project.setName("EMBEDDED_" + externalUserId);
265:                 project.setWorkspaceId(Workspace.DEFAULT_WORKSPACE_ID);
266: 
267:                 project = projectService.create(project);
268: 
269:                 ConnectedUser connectedUser = connectedUserService.getConnectedUser(externalUserId, environment);
270: 
271:                 return connectUserProjectService.create(connectedUser.getId(), project.getId());
272:             });
273:     }
