275:     private void checkWorkflowNodeConnection(
276:         String map, List<Connection> connections, ProjectWorkflow projectWorkflow, String workflowNodeName) {
277: 
278:         WorkflowNodeType workflowNodeType = WorkflowNodeType.ofType(map);
279: 
280:         connections.stream()
281:             .filter(connection -> Objects.equals(connection.getComponentName(), workflowNodeType.name()))
282:             .findFirst()
283:             .ifPresent(connection -> workflowTestConfigurationFacade.saveWorkflowTestConfigurationConnection(
284:                 projectWorkflow.getWorkflowId(), workflowNodeName, workflowNodeType.name(),
285:                 connection.getId()));
286:     }
287: 
288:     private void checkWorkflowNodeConnections(
289:         Map<String, ?> workflowMap, List<Connection> connections, ProjectWorkflow projectWorkflow) {
290: 
291:         List<Map<String, ?>> triggers = MapUtils.getList(workflowMap, "triggers", new TypeReference<>() {}, List.of());
292: 
293:         for (Map<String, ?> triggerMap : triggers) {
294:             checkWorkflowNodeConnection(
295:                 MapUtils.getString(triggerMap, "type"), connections, projectWorkflow,
296:                 MapUtils.getString(triggerMap, "name"));
297:         }
298: 
299:         List<Map<String, ?>> tasks = MapUtils.getList(workflowMap, "tasks", new TypeReference<>() {}, List.of());
300: 
301:         for (Map<String, ?> taskMap : tasks) {
302:             checkWorkflowNodeConnection(
303:                 MapUtils.getString(taskMap, "type"), connections, projectWorkflow, MapUtils.getString(taskMap, "name"));
304:         }
305:     }
306: }
