290: 
291:         List<Map<String, ?>> triggers = MapUtils.getList(workflowMap, "triggers", new TypeReference<>() {}, List.of());
292: 
293:         for (Map<String, ?> triggerMap : triggers) {
294:             checkWorkflowNodeConnection(
295:                 MapUtils.getString(triggerMap, "type"), connections, projectWorkflow,
296:                 MapUtils.getString(triggerMap, "name"));
297:         }
298: 
299:         List<Map<String, ?>> tasks = MapUtils.getList(workflowMap, "tasks", new TypeReference<>() {}, List.of());
300: 
