+
+    const isOnline = onlineManager.isOnline();
+
+    // if (!project) {
+    //     return <WorkflowBuilderSkeleton />;
+    // }
+
+    return (
+        <header className="flex items-center justify-between bg-surface-main px-3 py-2.5">
