+                                    {label: 'Production', value: 3},
+                                ]?.map((item) => (
+                                    <LeftSidebarNavItem
+                                        item={{
+                                            current: environment === item.value,
+                                            id: item.value,
+                                            name: item.label,
+                                        }}
+                                        key={item.value ?? ''}
+                                        toLink={`?environment=${item.value ?? ''}`}
+                                    />
+                                ))}
+                            </>
+                        }
+                        title="Environments"
+                    />
+                </>
+            }
