+    ConnectedUserProjectWorkflowKeys,
+    useGetConnectedUserProjectWorkflowQuery,
+} from '@/shared/queries/embedded/connectedUserProjectWorkflows.queries';
+import {useQueryClient} from '@tanstack/react-query';
