354:     private static ApplyFunction getDefaultApplyFunction(AuthorizationType type) {
355:         return switch (type) {
356:             case API_KEY -> (Parameters connectionParameters, Context context) -> {
357:                 String addTo = MapUtils.getString(
358:                     connectionParameters, Authorization.ADD_TO, ApiTokenLocation.HEADER.name());
359: 
360:                 if (ApiTokenLocation.valueOf(addTo.toUpperCase()) == ApiTokenLocation.HEADER) {
361:                     return ApplyResponse.ofHeaders(
362:                         Map.of(
363:                             MapUtils.getString(connectionParameters, Authorization.KEY, Authorization.API_TOKEN),
364:                             List.of(MapUtils.getString(connectionParameters, Authorization.VALUE, ""))));
365:                 } else {
366:                     return ApplyResponse.ofQueryParameters(
367:                         Map.of(
368:                             MapUtils.getString(connectionParameters, Authorization.KEY, Authorization.API_TOKEN),
369:                             List.of(MapUtils.getString(connectionParameters, Authorization.VALUE, ""))));
370:                 }
371:             };
372:             case BASIC_AUTH, DIGEST_AUTH -> (Parameters connectionParameters, Context context) -> {
373:                 String valueToEncode =
374:                     MapUtils.getString(connectionParameters, Authorization.USERNAME) +
375:                         ":" + MapUtils.getString(connectionParameters, Authorization.PASSWORD);
376: 
377:                 return ApplyResponse.ofHeaders(
378:                     Map.of(
379:                         "Authorization",
380:                         List.of(
381:                             "Basic " +
382:                                 EncodingUtils.base64EncodeToString(valueToEncode.getBytes(StandardCharsets.UTF_8)))));
383:             };
384:             case BEARER_TOKEN -> (Parameters connectionParameters, Context context) -> ApplyResponse.ofHeaders(
385:                 Map.of(
386:                     Authorization.AUTHORIZATION,
387:                     List.of(
388:                         Authorization.BEARER + " " + MapUtils.getString(connectionParameters, Authorization.TOKEN))));
389:             case CUSTOM -> (Parameters connectionParameters, Context context) -> null;
390:             case OAUTH2_AUTHORIZATION_CODE, OAUTH2_AUTHORIZATION_CODE_PKCE, OAUTH2_CLIENT_CREDENTIALS,
391:                 OAUTH2_IMPLICIT_CODE, OAUTH2_RESOURCE_OWNER_PASSWORD -> (
392:                     Parameters connectionParameters, Context context) -> ApplyResponse.ofHeaders(
393:                         Map.of(
394:                             Authorization.AUTHORIZATION,
395:                             List.of(
396:                                 MapUtils.getString(
397:                                     connectionParameters, Authorization.HEADER_PREFIX,
398:                                     Authorization.BEARER) +
399:                                     " " +
400:                                     MapUtils.getRequiredString(connectionParameters, Authorization.ACCESS_TOKEN))));
401:         };
402:     }
