458:         RefreshTokenFunction refreshTokenFunction, RefreshUrlFunction refreshUrlFunction) {
459: 
460:         return (connectionParameters, context) -> {
461:             FormBodyPublisher.Builder builder = FormBodyPublisher.newBuilder();
462: 
463:             builder.query("client_id", clientIdFunction.apply(connectionParameters, context));
464:             builder.query("client_secret", clientSecretFunction.apply(connectionParameters, context));
465:             builder.query("refresh_token", refreshTokenFunction.apply(connectionParameters, context));
466:             builder.query("grant_type", "refresh_token");
467: 
468:             try (HttpClient httpClient = Methanol.newBuilder()
469:                 .version(HttpClient.Version.HTTP_1_1)
470:                 .build()) {
471: 
472:                 HttpResponse<String> httpResponse = httpClient.send(
473:                     HttpRequest.newBuilder()
474:                         .POST(builder.build())
475:                         .uri(URI.create(refreshUrlFunction.apply(connectionParameters, context)))
476:                         .header("Accept", "application/json")
477:                         .build(),
478:                     HttpResponse.BodyHandlers.ofString());
479: 
480:                 if (httpResponse.statusCode() < 200 || httpResponse.statusCode() > 299) {
481:                     throw new ConfigurationException(
482:                         "OAuth provider rejected token refresh request",
483:                         ConnectionDefinitionErrorType.GET_DEFAULT_REFRESH_URL);
484:                 }
485: 
486:                 if (httpResponse.body() == null) {
487:                     throw new ConfigurationException(
488:                         "Unable to locate access_token, body content misses",
489:                         ConnectionDefinitionErrorType.GET_DEFAULT_AUTHORIZATION_CALLBACK_FUNCTION);
490:                 }
491: 
492:                 Map<String, Object> responseMap = JsonUtils.read(httpResponse.body(), new TypeReference<>() {});
493: 
494:                 return new RefreshTokenResponse(
495:                     (String) responseMap.get(Authorization.ACCESS_TOKEN),
496:                     (String) responseMap.get(Authorization.REFRESH_TOKEN),
497:                     responseMap.containsKey(Authorization.EXPIRES_IN)
498:                         ? Long.valueOf((Integer) responseMap.get(Authorization.EXPIRES_IN)) : null);
499:             }
500:         };
501:     }
