+            .thenReturn("2");
+
+        when(testContext.http(any()))
+            .thenReturn(testExecutor);
+        when(testExecutor.header(testNameArgumentCaptor.capture(), testValueArgumentCaptor.capture()))
+            .thenReturn(testExecutor);
+        when(testExecutor.queryParameters(testQueryArgumentCaptor.capture()))
+            .thenReturn(testExecutor);
+        when(testExecutor.body(testBodyArgumentCaptor.capture()))
+            .thenReturn(testExecutor);
+        when(testExecutor.configuration(any()))
+            .thenReturn(testExecutor);
+        when(testResponse.getHeaders())
+            .thenReturn(Map.of(LOCATION, List.of("url")));
+        when(testExecutor.execute())
+            .thenReturn(testResponse);
+        when(testResponse.getBody(any(TypeReference.class)))
+            .thenReturn(Map.of(SNIPPET, Map.of()));
+
+        Map<String, Object> result = YoutubeUploadVideoAction.perform(
+            testParameters, testParameters, testContext);
+
+        assertEquals(Map.of(), result);
+
+        assertEquals(List.of("Content-Type", "Content-Type"), testNameArgumentCaptor.getAllValues());
+        assertEquals(List.of("application/octet-stream", "application/octet-stream"),
+            testValueArgumentCaptor.getAllValues());
+
+        Object[] queryArguments = testQueryArgumentCaptor.getValue();
+        Object[] expectedQueryArguments = {
