56: public class CryptoHelperPGPEncryptAction {
57: 
58:     public static final ModifiableActionDefinition ACTION_DEFINITION = action("PGPencrypt")
59:         .title("PGP Encrypt")
60:         .description("Encrypts the file using PGP public key.")
61:         .properties(
62:             string(PUBLIC_KEY)
63:                 .label("Public PGP Key")
64:                 .description(
65:                     "Public PGP key of the recipient of the encrypted file. Make sure there is a new line after the PGP header.")
66:                 .controlType(ControlType.TEXT_AREA)
67:                 .required(true),
68:             fileEntry(FILE)
69:                 .label("File")
70:                 .description("File that will be encrypted.")
71:                 .required(true))
72:         .output(
73:             outputSchema(
74:                 fileEntry()
75:                     .description("PGP encrypted file.")))
76:         .perform(CryptoHelperPGPEncryptAction::perform);
77: 
78:     private CryptoHelperPGPEncryptAction() {
79:     }
80: 
81:     public static FileEntry perform(Parameters inputParameters, Parameters connectionParameters, Context context)
82:         throws IOException, PGPException {
83: 
84:         Security.addProvider(new BouncyCastleProvider());
85: 
86:         String publicKeyArmoredText = inputParameters.getRequiredString(PUBLIC_KEY);
87: 
88:         InputStream publicKeyInputStream = PGPUtil.getDecoderStream(
89:             new ByteArrayInputStream(publicKeyArmoredText.getBytes(StandardCharsets.UTF_8)));
90: 
91:         JcaPGPPublicKeyRingCollection pgpPublicKeyRingCollection = new JcaPGPPublicKeyRingCollection(
92:             publicKeyInputStream);
93: 
94:         publicKeyInputStream.close();
95: 
96:         PGPPublicKey pgpPublicKey = getPublicKey(pgpPublicKeyRingCollection);
97: 
98:         byte[] inputFileBytes = context.file(file -> file.readAllBytes(inputParameters.getRequiredFileEntry(FILE)));
99: 
100:         PGPDataEncryptorBuilder encryptorBuilder = new JcePGPDataEncryptorBuilder(PGPEncryptedData.CAST5)
101:             .setProvider(BouncyCastleProvider.PROVIDER_NAME)
102:             .setSecureRandom(new SecureRandom())
103:             .setWithIntegrityPacket(true);
104: 
105:         PGPEncryptedDataGenerator pgpEncryptedDataGenerator = new PGPEncryptedDataGenerator(encryptorBuilder);
106: 
107:         pgpEncryptedDataGenerator.addMethod(
108:             new JcePublicKeyKeyEncryptionMethodGenerator(pgpPublicKey)
109:                 .setProvider(BouncyCastleProvider.PROVIDER_NAME));
110: 
111:         ByteArrayOutputStream encryptedDataOutputStream = new ByteArrayOutputStream();
112: 
113:         try (OutputStream cOut = pgpEncryptedDataGenerator.open(encryptedDataOutputStream, inputFileBytes.length)) {
114:             cOut.write(inputFileBytes);
115:         }
116: 
117:         String armoredMessage = armorMessage(encryptedDataOutputStream.toByteArray());
118: 
119:         return context.file(
120:             file -> file.storeContent("encrypted.",
121:                 new ByteArrayInputStream(armoredMessage.getBytes(StandardCharsets.UTF_8))));
122:     }
123: 
124:     private static PGPPublicKey getPublicKey(JcaPGPPublicKeyRingCollection pgpPublicKeyRingCollection) {
125:         PGPPublicKey publicKey = null;
126:         Iterator<PGPPublicKeyRing> keyRingIterator = pgpPublicKeyRingCollection.getKeyRings();
127: 
128:         while (keyRingIterator.hasNext()) {
129:             PGPPublicKeyRing keyRing = keyRingIterator.next();
130:             Iterator<PGPPublicKey> keyIter = keyRing.getPublicKeys();
131: 
132:             while (keyIter.hasNext()) {
133:                 PGPPublicKey key = keyIter.next();
134: 
135:                 if (key.isEncryptionKey()) {
136:                     publicKey = key;
137: 
138:                     break;
139:                 }
140:             }
141:         }
142: 
143:         return publicKey;
144:     }
145: 
146:     private static String armorMessage(byte[] encryptedData) throws IOException {
147:         ByteArrayOutputStream byteArrayOutputStream = new ByteArrayOutputStream();
148: 
149:         ArmoredOutputStream armoredOutputStream = new ArmoredOutputStream(byteArrayOutputStream);
150: 
151:         armoredOutputStream.write(encryptedData);
152:         armoredOutputStream.close();
153: 
154:         return byteArrayOutputStream.toString(StandardCharsets.UTF_8);
155:     }
156: }
